-- Daily challenges for 2026-10-22: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-22. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('laughing-more-often', 'Laughing More Often', 'For anyone who can''t remember the last time they laughed out loud. Each day is one small way to invite more humor and lightness in, from a silly video shared with a friend to noticing the funny side of a small mishap.', 'Play', 365, array['Self-Care', 'Stress', 'Relationships']::text[], 1, '2026-10-22T17:00:00+00:00'::timestamptz),
  ('loosening-old-grudges', 'Loosening Old Grudges', 'For anyone still carrying anger about something that happened a while ago. Each day is one small step toward setting it down for your own sake, at your own pace, without having to excuse what happened or reconnect with anyone.', 'Relationships', 365, array['Anger', 'Emotion Regulation', 'Relationships']::text[], 1, '2026-10-22T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('laughing-more-often', 'loosening-old-grudges');

